          "code": "import java.util.*;\n\npublic class Main {\n    public static int lengthOfLIS(int[] nums) {\n        int[] tails = new int[nums.length];\n        int size = 0;\n        for (int x : nums) {\n            int i = 0, j = size;\n            while (i != j) {\n                int m = (i + j) / 2;\n                if (tails[m] < x) i = m + 1;\n                else j = m;\n            }\n            tails[i] = x;\n            if (i == size) size++;\n        }\n        return size;\n    }\n    public static void main(String[] args) {\n        System.out.println(\"LIS: \" + lengthOfLIS(new int[]{10,9,2,5,3,7,101,18}));\n    }\n}",
