          "code": "import java.util.Arrays;\n\npublic class Main {\n    public static int uniquePaths(int m, int n) {\n        int[] dp = new int[n];\n        Arrays.fill(dp, 1);\n        for (int i = 1; i < m; i++) {\n            for (int j = 1; j < n; j++) {\n                dp[j] += dp[j - 1];\n            }\n        }\n        return dp[n - 1];\n    }\n    public static void main(String[] args) {\n        System.out.println(\"Paths 3x7: \" + uniquePaths(3, 7));\n    }\n}",
